# The ChatDisplayMask identifies that types of chat that are displayed in each chat window.<para />
# Used by CharacterOptionData: The CharacterOptionData structure contains character options.
class ChatDisplayMask(IntEnum):
    Gameplay = 0x3912021
    Mandatory = 0xc302
    AreaChat = 0x1004
    Tells = 0x18
    Combat = 0x600040
    Magic = 0x20080
    Allegiance = 0x40c00
    Fellowship = 0x80000
    Errors = 0x4000000
    GeneralChannel = 0x8000000
    TradeChannel = 0x10000000
    LFGChannel = 0x20000000
    RoleplayChannel = 0x40000000

# The ChatFilterMask identifies types of messages that are squelched or filtered (/messagetypes).<para />
# Used with F7B0 01F4: Game Event -> Squelch and Filter List
class ChatFilterMask(IntFlag):
    Speech = 0x4
    Tell = 0x8
    Combat = 0x40
    Magic = 0x80
    Emote = 0x1000
    Appraisal = 0x10000
    Spellcasting = 0x20000
    Allegiance = 0x40000
    Fellowship = 0x80000
    Combat_Enemy = 0x200000
    Combat_Self = 0x400000
    Recall = 0x800000
    Craft = 0x1000000
    Salvaging = 0x2000000
    AllMessageTypes = 0xffffffff

# The ChatMessageType categorizes chat window messages to control color and filtering.<para />
# Used with 02BB: Creature Message<para />
# 0x02, 0x0C, 0x11
# Used with 02BC: Creature Message (Ranged)<para />
# 0x0C
# Used with F7B0 02BD: Game Event -> Someone has sent you a @tell.<para />
# 0x03,
# Used with F7E0: Server Message
# 0x00, 0x03, 0x04, 0x05, 0x06, 0x07, 0x0D, 0x10, 0x11, 0x17, 0x18
class ChatMessageType(IntEnum):
    Broadcast = 0x0
    AllChannels = 0x1
    Speech = 0x2
    Tell = 0x3
    OutgoingTell = 0x4
    System = 0x5
    Combat = 0x6
    Magic = 0x7
    Channel = 0x8
    ChannelSend = 0x9
    Social = 0xa
    SocialSend = 0xb
    Emote = 0xc
    Advancement = 0xd
    Abuse = 0xe
    Help = 0xf
    Appraisal = 0x10
    Spellcasting = 0x11
    Allegiance = 0x12
    Fellowship = 0x13
    WorldBroadcast = 0x14
    CombatEnemy = 0x15
    CombatSelf = 0x16
    Recall = 0x17
    Craft = 0x18
    Salvaging = 0x19
    x1B = 0x1b
    x1C = 0x1c
    x1D = 0x1d
    x1E = 0x1e
    AdminTell = 0x1f

